-- Create "language_settings" table
CREATE TABLE "language_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "translatable_types" jsonb NULL, "untranslated" character varying NOT NULL DEFAULT 'original', PRIMARY KEY ("id"));
-- Create "language_visibility" table
CREATE TABLE "language_visibility" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" character varying NOT NULL, "ref" character varying NOT NULL, "langs" jsonb NOT NULL, PRIMARY KEY ("id"));
-- Create index "language_visibility_kind_ref" to table: "language_visibility"
CREATE UNIQUE INDEX "language_visibility_kind_ref" ON "language_visibility" ("kind", "ref");
-- Create "text_translations" table
CREATE TABLE "text_translations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" character varying NOT NULL, "ref" character varying NOT NULL, "lang" character varying NOT NULL, "value" text NOT NULL, PRIMARY KEY ("id"));
-- Create index "text_translations_kind_ref_lang" to table: "text_translations"
CREATE UNIQUE INDEX "text_translations_kind_ref_lang" ON "text_translations" ("kind", "ref", "lang");
-- Create "node_translations" table
CREATE TABLE "node_translations" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "tnid" bigint NOT NULL, "outdated" boolean NOT NULL DEFAULT false, "nid" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "node_translations_nodes_node" FOREIGN KEY ("nid") REFERENCES "nodes" ("id") ON DELETE CASCADE);
-- Create index "node_translations_nid" to table: "node_translations"
CREATE UNIQUE INDEX "node_translations_nid" ON "node_translations" ("nid");
-- Create index "node_translations_tnid" to table: "node_translations"
CREATE INDEX "node_translations_tnid" ON "node_translations" ("tnid");
